import{_ as a,o as l,c as t,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const p=JSON.parse('{"title":"Ceph Performance Meeting 2022-06-30","description":"","frontmatter":{"title":"Ceph Performance Meeting 2022-06-30","date":"2022-06-30T00:00:00.000Z","updated":"2022-07-01T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","RocksDB","博客文章"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2022/Ceph_Performance_Meeting_2022-06-30.md","filePath":"posts/2022/Ceph_Performance_Meeting_2022-06-30.md","lastUpdated":1780459816000}'),r={name:"posts/2022/Ceph_Performance_Meeting_2022-06-30.md"};function o(n,e,s,h,c,d){return l(),t("div",null,[...e[0]||(e[0]=[i('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ol><li><p><strong>新的Pull Request讨论</strong></p><ul><li>会议开始讨论了新的Pull Request情况，目前只有一个关于RGW（RADOS Gateway）原子写入器的基准测试组件的PR。该组件是Zipper工作的一部分，旨在通过基准测试比较不同后端之间的性能。</li></ul></li><li><p><strong>博客文章更新</strong></p><ul><li>讨论了一篇关于RocksDB调优的博客文章，该文章由Kieran Singh和Daniel Parks撰写，提出了一些调优建议，但未经过QA测试，存在潜在问题和副作用。会议参与者对该设置的有效性和安全性表示担忧，建议可能需要更新或明确警告这些设置的风险。</li></ul></li><li><p><strong>后续行动计划</strong></p><ul><li>计划编写一篇新的RocksDB调优博客文章，详细解释设置及其可能的影响，并明确风险。</li><li>讨论了是否需要针对现有博客文章发布更正或警告，最终决定可能需要撰写一篇新的博客文章来解释这些设置的后果。</li></ul></li></ol><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li>确认需要编写一篇新的RocksDB调优博客文章，详细解释设置及其影响，并明确风险。</li><li>讨论了是否需要对现有博客文章进行更正或警告，但最终决定可能通过新的博客文章来解决这些问题。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li>编写新的RocksDB调优博客文章，并邀请团队成员在发布前进行审阅和反馈。</li><li>继续关注OSD线程行为的研究，预计下周继续相关工作。</li></ul><h4 id="其他事项" tabindex="-1">其他事项 <a class="header-anchor" href="#其他事项" aria-label="Permalink to &quot;其他事项&quot;">​</a></h4><ul><li>会议结束时，提醒美国团队成员即将到来的假期，并祝愿所有人周末愉快。</li></ul><h3 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h3><p>会议主要围绕新的PR和现有博客文章的更新进行了讨论，确定了编写新博客文章的计划，并讨论了现有文章的潜在问题和解决方案。会议在确认后续行动计划后结束，祝愿所有人周末愉快。</p>',11)])])}const _=a(r,[["render",o]]);export{p as __pageData,_ as default};
